                <img className="img-fluid rounded-5 images-body " src="https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQEKxVwXGC5kGVDnEQi3k3ujzn_vEw-qPszsw&s" alt="" />
            </div>
        </div>
    </div>
  );
};

export default FoodCards;
